import manifest from './images.generated.json';

/** Generated by scripts/images.ts — do not edit images.generated.json by hand. */
export type ImageKey = keyof typeof manifest;

export interface ImageEntry {
  kind: 'photo' | 'illustration';
  /** Intrinsic size of the source image. */
  width: number;
  height: number;
  /** Widths available in public/images as `${base}-${w}.avif|webp`. */
  widths: number[];
  base: string;
  /** Tiny WebP data URI for photos; null for transparent illustrations. */
  blur: string | null;
  source: string;
}

export const images = manifest as Record<ImageKey, ImageEntry>;

export const isTeamPortrait = (key: ImageKey) => key.startsWith('team');

/**
 * Message key for an image's alt text. Team portraits share one key that takes the
 * member's name: t(altKeyFor(key), { name }).
 */
export function altKeyFor(key: ImageKey): string {
  return isTeamPortrait(key) ? 'common.alt.teamPortrait' : `common.alt.${key}`;
}
